    /**
     * Error code (0 = no error)
     */
    error_code?: number;
    /**
     * Human-readable error name
     */
    error_name?: string;
    /**
     * Check duration in milliseconds
     */
    duration_ms?: (number) | null;
    /**
     * TLS certificate NotAfter timestamp (HTTPS endpoints only)
     */
    ssl_cert_not_after?: (string) | null;
    /**
     * DNS lookup duration in milliseconds
     */
    http_dns_lookup_ms?: (number) | null;
    /**
     * TCP connection duration in milliseconds
     */
    http_tcp_connect_ms?: (number) | null;
    /**
     * TLS handshake duration in milliseconds
     */
    http_tls_handshake_ms?: (number) | null;
    /**
     * Time to first byte in milliseconds
     */
    http_time_to_first_byte_ms?: (number) | null;
    /**
     * HTTP response body size in bytes
     */
    http_response_size_bytes?: (number) | null;
    /**
     * TLS version string (e.g. 'TLS 1.3')
     */
    http_tls_version?: (string) | null;
    /**
     * Resolved IP address of the endpoint hostname (HTTP legacy)
     */
    http_resolved_ip?: (string) | null;
    /**
     * Resolved IP address of the endpoint hostname (generic, all check types)
     */
    resolved_ip?: (string) | null;
    /**
     * Error category (timeout/connection/dns/network/response/configuration/other)
     */
    http_error_category?: (string) | null;
    /**
     * Whether the TLS certificate is currently valid
     */
    http_tls_valid?: (boolean) | null;
    /**
     * Days until TLS certificate expiry
     */
    http_tls_days_until_expiry?: (number) | null;
    /**
     * TLS certificate issuer CommonName
     */
    http_tls_issuer?: (string) | null;
    /**
     * TLS certificate subject CommonName
     */
    http_tls_subject?: (string) | null;
    /**
     * Average round-trip time in milliseconds
     */
