/**
 * Full Workspace serializer for CRUD operations.
 *
 * Inherits ManagedObject fields (last_action_run, icon_url, SLO/SLA, etc.)
 * per polycrate spec inspect 36 — same pattern as K8sClusterSerializer.
 *
 * Supports template-based creation using template name (slug).
 * Template can be org-specific or system-wide (organization=null).
 */
export type WorkspaceRequest = {
    /**
     * Object name
     */
    name?: string;
    /**
     * The display name is used to display the object in the UI. It can be different from the name.
     */
    display_name?: (string) | null;
    labels?: unknown;
    annotations?: unknown;
    /**
     * Persists all Object Logs in the database
     */
    debug_mode?: boolean;
    provider?: ProviderEnum;
    provider_reference?: (string) | null;
    provider_id?: (string) | null;
    reconciliation_enabled?: boolean;
    discovery_enabled?: boolean;
    platform_service?: boolean;
    /**
     * The scope is used to separate `system` owned objects from `user` owned objects.
     *
     * * `system` - System
     * * `user` - User
     */
    scope?: (ScopeEnum);
    kind?: WorkspaceKindEnum;
    /**
     * Archived objects are not shown in the UI and are not managed by the API.
     */
    archived?: boolean;
    archived_at?: (string) | null;
    /**
     * The reason why the object was archived
     */
    archived_reason?: (string) | null;
    /**
     * Criticality level. Null = inherit from workspace, then org. Explicit value overrides inheritance.
     *
     * * `high` - High
     * * `medium` - Medium
     * * `low` - Low
     */
    criticality?: ((CriticalityEnum | BlankEnum | NullEnum) | null);
    /**
     * Target availability in % (overrides SystemConfig default). Null = use SystemConfig DEFAULT_TARGET_AVAILABILITY.
     */
    target_availability?: (string) | null;
    /**
     * Calculated actual availability as yearly average in %
     */
    actual_availability?: string;
    /**
     * Internal SLO target in %. Null = use SystemConfig DEFAULT_SLO_TARGET
     */
    slo_target?: (string) | null;
    /**
     * Calculated SLO availability in % (updated in reconcile)
     */
    slo_availability?: string;
    /**
     * Contractual SLA target in %. Null = use SystemConfig DEFAULT_SLA_TARGET
     */
    sla_target?: (string) | null;
    /**
     * Calculated SLA availability in % (updated in reconcile)
     */
    sla_availability?: string;
    gitlab_project_id?: (number) | null;
    /**
     * GitLab project URL (e.g., https://gitlab.com/user/project)
     */
    gitlab_project_url?: ((string) | null);
    /**
     * If true, this workspace runs in a customer-managed environment that is not reachable from ayedo infrastructure. Endpoints in this workspace will only be monitored by the workspace's own agent — external global monitors are excluded. Also disables K8sCluster API server reachability checks for clusters in this workspace.
     */
    on_premise?: boolean;
    /**
     * Defines which endpoints the workspace agent is allowed to monitor (Reach-Out scope)
     *
     * * `auto` - AUTO - Monitor everything
     * * `organization_only` - ORGANIZATION_ONLY - Only monitor endpoints from same organization
     * * `workspace_only` - WORKSPACE_ONLY - Only monitor endpoints from same workspace
     * * `pop_only` - POP_ONLY - Only monitor endpoints from same pop
     */
    endpoint_monitoring_mode?: (WorkspaceEndpointMonitoringModeEnum);
    /**
     * If true, the agent of this workspace receives endpoints from OTHER workspaces (subject to endpoint_monitoring_mode and target workspace's monitoring_workspace_allowlist). If false (default), agent only monitors own workspace's endpoints.
     */
    global_endpoint_monitor?: boolean;
    monitoring_workspace_allowlist_ids?: Array<(string)>;
    notifications_enabled?: boolean;
    /**
     * If false, ayedo does not evaluate workspace-level backup health (WORKSPACE_BACKUP_SCHEDULE_MISSING, WORKSPACE_BACKUP_SCHEDULE_OVERDUE, WORKSPACE_BACKUP_MISSING). Use when ayedo is not responsible for backups. May later gate related backup features; bucket provisioning stays independent for now.
     */
    backup_enabled?: boolean;
    /**
     * If false, ayedo does not auto-subscribe the VictoriaMetrics agent addon. Use when this workspace must not scrape or send cluster metrics.
     */
    metrics_enabled?: boolean;
    /**
     * If false, ayedo does not auto-subscribe VictoriaLogs or Kubernetes Event Exporter. Use when this workspace must not scrape or send cluster logs.
     */
    logs_enabled?: boolean;
    /**
     * If false, cluster reconcile does not run K8s addon subscription desired-state (no auto-subscribe, no addon install enqueue, no addon conditions). Subscribe, promote, and the cluster Addons tab are unavailable. Use while this workspace is still git-managed via workspace.poly.
     */
    k8s_addons_enabled?: boolean;
    has_incompatible_kubeconfig?: boolean;
    endpoint_monitors?: Array<(string)>;
    /**
     * Content of the secrets.poly file (sensitive data)
     */
    secrets_poly_raw?: (string) | null;
    workspace_inventory_raw?: (string) | null;
    organization_id?: (string) | null;
    /**
     * Indicates if workspace is encrypted (contains .workspace-encrypted file)
     */
    encrypted?: boolean;
    pop_id: string;
    /**
     * Name of the workspace template to use (write-only)
     */
    template?: (string) | null;
    /**
     * Short free-text description of this workspace
     */
    description?: (string) | null;
    /**
     * Purpose of this workspace (production, development, staging, qa, infrastructure, platform)
     *
     * * `production` - Production
     * * `development` - Development
     * * `staging` - Staging
     * * `qa` - QA
     * * `infrastructure` - Infrastructure
     * * `platform` - Platform
     */
    purpose?: ((PurposeF3bEnum | BlankEnum | NullEnum) | null);
    /**
     * Named URLs for this workspace, e.g. [{"name": "Runbook", "url": "https://..."}]
     */
    urls?: unknown;
    owner_id?: (number) | null;
    readme_md?: (string) | null;
    alternative_name?: (string) | null;
};

